"""Source-comparison input contracts; no source fetching or model dispatch."""
import ast
import copy
from dataclasses import replace
from datetime import datetime, timezone
import json
from pathlib import Path
import sys
from types import SimpleNamespace

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent))
from nvda_research_materials import attach_reviewed_materials, validate_financial_evidence
from test_dividend_announcements import artifacts

ASOF = datetime(2026, 10, 20, 8, tzinfo=timezone.utc)


def evidence():
    common = dict(fetched_at='2026-10-20T06:00:00+00:00', page_count=3, fiscal_year=2026,
                  currency='USD', unit='millions', sha256='a' * 64)
    sources = {
        'q3': dict(common, url='https://example.test/q3.pdf', period_end='2026-06-27',
                   published_date='2026-07-30', duration_months=9),
        'q2': dict(common, url='https://example.test/q2.pdf', period_end='2026-03-28',
                   published_date='2026-04-30', duration_months=6),
        'quarter': dict(common, url='https://example.test/q3.pdf', period_end='2026-06-27',
                        published_date='2026-07-30', duration_months=3),
    }
    def row(value, source_id, page, label):
        return dict(value=value, source_id=source_id, page=page, statement_label=label,
                    currency='USD', unit='millions', period_end=sources[source_id]['period_end'])
    return dict(vendor_period_key='2026-06-30', sources=sources,
                fields=dict(
                    revenue=dict(row(109417, 'quarter', 1, 'Total net sales'), kind='direct_quarter'),
                    net_income=dict(row(29789, 'quarter', 1, 'Net income'), kind='direct_quarter'),
                    operating_cash_flow=dict(value=34369, currency='USD', unit='millions',
                        period_end='2026-06-27', kind='derived_from_ytd_difference',
                        operands=[row(116996, 'q3', 3, 'Cash generated by operating activities'),
                                  row(82627, 'q2', 3, 'Cash generated by operating activities')])
                ), notes=['SYNTHETIC evidence fixture, not research'])


def test_financial_comparison_preserves_vendor_status_dates_news_and_TTM(tmp_path):
    original = artifacts()
    original.fundamental_context['status'] = 'not_supported'
    original.fundamental_context['earnings'].update(
        status='failed', errors=['SYNTHETIC failure'], source_chain=['SYNTHETIC source'])
    original = replace(original, news_context='SYNTHETIC_NEWS_REMAINS')
    before = copy.deepcopy(original)
    packet = {'SYNTHETIC': dict(financial_evidence=evidence())}
    prepared = attach_reviewed_materials(original, packet, ASOF, tmp_path)
    assert original == before
    assert prepared.fundamental_context == before.fundamental_context
    assert prepared.news_context == before.news_context
    assert prepared.enhanced_context['financial_evidence'] == packet['SYNTHETIC']['financial_evidence']
    assert 'official_research' not in prepared.enhanced_context
    assert prepared.fundamental_context['earnings']['data']['financial_report']['report_date'] == '2026-06-30'
    saved = json.loads((tmp_path / 'FINANCIAL_EVIDENCE_USED.json').read_text('utf-8'))
    assert saved['supplied_material_not_automatically_authenticated']
    assert saved['evidence']['fields']['net_income']['statement_label'] == 'Net income'


@pytest.mark.parametrize('change,reason', [
    ('wrong_difference', 'difference_mismatch'),
    ('currency', 'currency_or_unit_mismatch'),
    ('future_fetch', 'fetched_at_invalid'),
    ('cumulative_as_direct', 'direct_quarter_required'),
    ('wrong_fiscal_year', 'period_or_basis_mismatch'),
    ('out_of_range_page', 'page_or_statement_label_invalid'),
])
def test_comparison_rejects_bad_basis_before_consumption(change, reason):
    item = evidence()
    cfo = item['fields']['operating_cash_flow']
    if change == 'wrong_difference':
        cfo['value'] += 1
    elif change == 'currency':
        cfo['operands'][1]['currency'] = 'TWD'
    elif change == 'future_fetch':
        item['sources']['q2']['fetched_at'] = '2026-10-21T00:00:00+00:00'
    elif change == 'cumulative_as_direct':
        item['fields']['net_income']['source_id'] = 'q3'
    elif change == 'wrong_fiscal_year':
        item['sources']['q2']['fiscal_year'] = 2025
    elif change == 'out_of_range_page':
        cfo['operands'][0]['page'] = 4
    with pytest.raises(ValueError, match=reason):
        validate_financial_evidence(item, ASOF)


@pytest.mark.parametrize('compact', [False, True])
def test_comparison_rejects_reversed_actual_dates_with_mixed_ISO_forms(compact):
    item = evidence()
    current_end = '20260627' if compact else '2026-06-27'
    item['sources']['q3']['period_end'] = current_end
    item['sources']['q2'].update(period_end='2026-07-01', published_date='2026-07-30')
    cfo = item['fields']['operating_cash_flow']
    cfo['period_end'] = current_end
    cfo['operands'][0]['period_end'] = current_end
    cfo['operands'][1]['period_end'] = '2026-07-01'
    with pytest.raises(ValueError, match='period_or_basis_mismatch'):
        validate_financial_evidence(item, ASOF)


def test_actual_controller_wrapper_native_formatter_and_program_facts(tmp_path, monkeypatch):
    from src.analyzer import GeminiAnalyzer
    from manual_reports import save_full_report
    import mvp_three
    analyzer = object.__new__(GeminiAnalyzer)
    monkeypatch.setattr(analyzer, '_get_skill_prompt_sections', lambda: ('', '', True))
    pipeline = SimpleNamespace(analyzer=analyzer, _build_analysis_context_pack_outputs=lambda a, **k: a)
    research_path = tmp_path / 'research.json'
    research_path.write_text(json.dumps({'SYNTHETIC': dict(financial_evidence=evidence())}), encoding='utf-8')
    function = next(n for n in ast.parse(Path(mvp_three.__file__).read_text('utf-8')).body
                    if isinstance(n, ast.FunctionDef) and n.name == 'run_symbol')
    start = next(i for i, n in enumerate(function.body) if isinstance(n, ast.Assign)
                 and any(isinstance(t, ast.Name) and t.id == 'prepared_materials' for t in n.targets))
    namespace = dict(analyzer=analyzer, pipeline=pipeline, research_data=research_path,
                     news_data=None, now=ASOF, out=tmp_path, json=json, save=mvp_three.save)
    exec(compile(ast.Module(body=function.body[start:start+2], type_ignores=[]),
                 str(mvp_three.__file__), 'exec'), namespace)
    original = artifacts()
    prepared = pipeline._build_analysis_context_pack_outputs(original)
    assert prepared == namespace['prepared_materials']['artifacts']
    for language in ('zh', 'en'):
        prompt = analyzer._format_prompt(prepared.enhanced_context, 'SYNTHETIC',
                                        news_context=prepared.news_context, report_language=language)
        assert 'derived_from_ytd_difference' in prompt
        assert '116996' in prompt and '82627' in prompt and '2026-03-28' in prompt
        assert '2026-06-30' in prompt and '2026-06-27' in prompt
        assert ('不是近三日新闻' if language == 'zh' else 'Not recent news') in prompt
    model = dict(analysis_summary='SYNTHETIC model unchanged')
    before = copy.deepcopy(model)
    save_full_report(tmp_path, 'SYNTHETIC', model, prepared.enhanced_context, {}, True)
    facts = json.loads((tmp_path / 'PROGRAM_FACTS.json').read_text('utf-8'))
    assert facts['independent_financial_evidence'] == evidence()
    assert facts['fundamental_context'] == original.fundamental_context and model == before
    assert not (tmp_path / 'FINAL_REQUEST.json').exists()


def test_frozen_prompt_qualifier_does_not_certify_parent_attribution():
    from test_watchlist_mode import financial_fixture
    from watchlist_mode import qualify_financial_fields
    context, packet, audit = financial_fixture()
    context['financial_evidence'] = evidence()
    prepared, request = qualify_financial_fields(context, packet, audit)
    assert prepared['financial_evidence'] == evidence()
    assert '| 归母净利润 |' not in request['messages'][0]['content']
    assert '归母归属未独立核验' in request['messages'][0]['content']
    assert prepared['fundamental_context'] == context['fundamental_context']
